+"""User administration routes for US-01."""
+
+from typing import Annotated
+
+from fastapi import Query, Response
+
+from core.base.router import BaseRouter, get, post
+from core.identity import AccountStatus
+from domains.worklink.schemas.system.user_admin import RowId, UserContact, UserContactRequest, UserDetail, UserList
+from domains.worklink.services.system.user_admin import UserAdminService
+
+Svc = Annotated[UserAdminService, UserAdminService.dep()]
+
+
+class UserRouter(BaseRouter):
+    menu = "screen-us-01"
+
+    @get("", summary="사용자 목록 조회")
+    async def list(
+        self,
+        response: Response,
+        svc: Svc,
+        search: Annotated[str | None, Query(max_length=254)] = None,
+        business_place_id: RowId | None = None,
+        department_id: RowId | None = None,
+        status: AccountStatus | None = None,
+    ) -> UserList:
+        response.headers["Cache-Control"] = "no-store"
+        return await svc.users(
+            search,
+            int(business_place_id) if business_place_id else None,
+            int(department_id) if department_id else None,
+            status,
+        )
+
+    @get("/{user_id}", summary="사용자 기본 정보와 조직 상세")
+    async def detail(self, user_id: RowId, response: Response, svc: Svc) -> UserDetail:
+        response.headers["Cache-Control"] = "no-store"
+        return await svc.detail(int(user_id))
+
+    @post("/{user_id}/contacts", summary="감사 이력을 남기고 사용자 연락처 원문 열람")
+    async def contacts(self, user_id: RowId, body: UserContactRequest, response: Response, svc: Svc) -> UserContact:
+        response.headers["Cache-Control"] = "no-store"
+        return await svc.contacts(int(user_id), int(body.business_place_id))
