index 00000000..52941f6c
--- /dev/null
+++ b/workspace/backend/src/domains/worklink/repository/system/user_admin.py
@@ -0,0 +1,137 @@
+"""Database reads for user administration and its organization scope."""
+
+from datetime import date
+
+from sqlalchemy import func, or_, select
+from sqlalchemy.ext.asyncio import AsyncSession
+from sqlalchemy.orm import aliased
+
+from core.audit import AuditLog
+from core.history import ChangeLog
+from core.identity import AccountStatus, UserBasic
+from domains.worklink.models.organization.business_place_basic import BusinessPlaceBasic
+from domains.worklink.models.organization.company_basic import CompanyBasic
+from domains.worklink.models.organization.department_basic import DepartmentBasic
+from domains.worklink.models.organization.organization import Organization
+from domains.worklink.models.organization.privacy_handler_log import PrivacyHandlerLog
+from domains.worklink.models.system.role import Role
+from domains.worklink.repository.organization.affiliation import active_department, employed
+
+PRIVACY_TARGET = "user_privacy_handler"
+CONTACT_VIEW_EVENT = "worklink.system.user.contacts.view"
+LOGIN_SUCCESS_EVENT = "auth.login.success"
+
+
+class UserAdminRepository:
+    def __init__(self, session: AsyncSession):
+        self.session = session
+
+    async def is_system_admin(self, user_id: int) -> bool:
+        return bool(
+            await self.session.scalar(
+                select(Role.fixed_role_yn)
+                .join(UserBasic, UserBasic.system_role_id == Role.role_id)
+                .where(UserBasic.user_id == user_id)
+            )
+        )
+
+    async def member_places(self, user_id: int, today: date) -> set[int]:
+        return set(
+            await self.session.scalars(
+                select(DepartmentBasic.business_place_id)
+                .join(Organization, Organization.department_id == DepartmentBasic.department_id)
+                .where(Organization.user_id == user_id, *active_department(today), *employed(today))
+                .distinct()
+            )
+        )
+
+    async def users(
+        self,
+        places: set[int] | None,
+        search: str | None,
+        department_id: int | None,
+        status: AccountStatus | None,
+    ):
+        stmt = select(UserBasic).order_by(UserBasic.user_name, UserBasic.user_id)
+        if search:
+            query = search.lower()
+            stmt = stmt.where(
+                or_(
+                    func.lower(UserBasic.user_name).contains(query, autoescape=True),
+                    func.lower(UserBasic.login_email).contains(query, autoescape=True),
+                )
+            )
+        if status is not None:
+            stmt = stmt.where(UserBasic.account_status_cd == status)
+        if places is not None or department_id is not None:
+            membership = (
+                select(Organization.organization_id)
+                .join(DepartmentBasic, DepartmentBasic.department_id == Organization.department_id)
+                .where(Organization.user_id == UserBasic.user_id)
+            )
+            if places is not None:
+                membership = membership.where(DepartmentBasic.business_place_id.in_(places))
+            if department_id is not None:
+                membership = membership.where(DepartmentBasic.department_id == department_id)
+            stmt = stmt.where(membership.exists())
+        return (await self.session.scalars(stmt)).all()
+
+    async def organizations(self, user_ids: list[int], places: set[int] | None, *, primary_only: bool = False):
+        parent = aliased(DepartmentBasic)
+        stmt = (
+            select(Organization, DepartmentBasic, BusinessPlaceBasic, CompanyBasic, parent.department_name)
+            .join(DepartmentBasic, DepartmentBasic.department_id == Organization.department_id)
+            .join(BusinessPlaceBasic, BusinessPlaceBasic.business_place_id == DepartmentBasic.business_place_id)
+            .join(CompanyBasic, CompanyBasic.company_id == BusinessPlaceBasic.company_id)
+            .outerjoin(
+                parent,
+                (parent.department_id == DepartmentBasic.parent_department_id)
+                & (parent.business_place_id == DepartmentBasic.business_place_id),
+            )
+            .where(Organization.user_id.in_(user_ids))
+            .order_by(Organization.primary_department_yn.desc(), Organization.organization_id)
+        )
+        if places is not None:
+            stmt = stmt.where(DepartmentBasic.business_place_id.in_(places))
+        if primary_only:
+            stmt = stmt.where(Organization.primary_department_yn.is_(True))
+        return (await self.session.execute(stmt)).all()
+
+    async def privacy_periods(self, user_ids: list[int]):
+        stmt = (
+            select(PrivacyHandlerLog)
+            .where(PrivacyHandlerLog.user_id.in_(user_ids))
+            .order_by(PrivacyHandlerLog.start_date)
+        )
+        return (await self.session.scalars(stmt)).all()
+
+    async def privacy_releases(self, user_ids: list[int]) -> set[int]:
+        latest = (
+            select(
+                ChangeLog.work_target_id,
+                ChangeLog.change_after_content,
+                func.row_number()
+                .over(
+                    partition_by=ChangeLog.work_target_id,
+                    order_by=(ChangeLog.create_dt.desc(), ChangeLog.change_log_id.desc()),
+                )
+                .label("position"),
+            )
+            .where(
+                ChangeLog.work_target_type_code == PRIVACY_TARGET,
+                ChangeLog.work_target_id.in_([str(user_id) for user_id in user_ids]),
+            )
+            .subquery()
+        )
+        rows = await self.session.execute(
+            select(latest.c.work_target_id, latest.c.change_after_content).where(latest.c.position == 1)
+        )
+        return {int(user_id) for user_id, content in rows if content and content.get("designated") is False}
+
+    async def last_login(self, user_id: int):
+        return await self.session.scalar(
+            select(func.max(AuditLog.create_dt)).where(
+                AuditLog.create_user_id == user_id,
+                AuditLog.event_code == LOGIN_SUCCESS_EVENT,
+            )
+        )
