+
+from core.identity import AccountStatus, Gender, UserLanguage
+
+RowId = Annotated[str, StringConstraints(pattern=r"^[1-9][0-9]{0,19}$")]
+
+
+class UserPrivacy(BaseModel):
+    state: Literal["unassigned", "scheduled", "active", "expired"]
+    start_date: date | None = None
+    finish_date: date | None = None
+    remaining_days: int | None = None
+    view: bool = False
+    process: bool = False
+    export: bool = False
