+
+class UserDepartment(BaseModel):
+    department_id: str
+    department_code: str
+    department_name: str
+    parent_department_name: str | None
+    business_place_id: str
+    business_place_code: str
+    business_place_name: str
+    company_code: str
+    company_name: str
+
+
+class UserSummary(BaseModel):
+    user_id: str
+    login_email: str
+    user_name: str
+    account_status_cd: AccountStatus
+    directory_suspended_yn: bool
+    primary_department: UserDepartment | None
+    mobile_phone: str | None
+    privacy: UserPrivacy
+
+
+class UserOrganization(BaseModel):
+    organization_id: str
