+    invite_expire_dt: datetime | None
+    last_login_dt: datetime | None
+    home_phone: str | None
+    address: str | None
+    first_hire_date: date | None
+    last_leave_date: date | None
+    use_language_cd: UserLanguage
+    discord_account: str | None
+    organizations: list[UserOrganization]
+
+
+class UserContactRequest(BaseModel):
+    business_place_id: RowId
+
+
+class UserContact(BaseModel):
+    mobile_phone: str | None
