diff --git a/workspace/backend/src/domains/worklink/services/system/user_admin.py b/workspace/backend/src/domains/worklink/services/system/user_admin.py
new file mode 100644
index 00000000..03b9a43d
--- /dev/null
+++ b/workspace/backend/src/domains/worklink/services/system/user_admin.py
@@ -0,0 +1,204 @@
+"""US-01 read policies, privacy projection and contact audit."""
+
+from collections import defaultdict
+from datetime import date
+from typing import Literal
+
+from fastapi import HTTPException
+
+from core.base.service import BaseService
+from core.config import get_settings
+from core.crypto import CryptoError, decrypt
+from core.identity import AccountStatus, UserBasic, user_phone_aad
+from core.masking import mask_phone
+from domains.worklink.models.organization.privacy_handler_log import PrivacyHandlerLog
+from domains.worklink.repository.system.user_admin import CONTACT_VIEW_EVENT, UserAdminRepository
+from domains.worklink.schemas.system.user_admin import (
+    UserContact,
+    UserDepartment,
+    UserDetail,
+    UserList,
+    UserOrganization,
+    UserPrivacy,
+    UserSummary,
+)
+
+
+def _department(dept, place, company, parent_name: str | None) -> UserDepartment:
+    return UserDepartment(
+        department_id=str(dept.department_id),
+        department_code=dept.department_code,
+        department_name=dept.department_name,
+        parent_department_name=parent_name,
+        business_place_id=str(place.business_place_id),
+        business_place_code=place.business_place_code,
+        business_place_name=place.business_place_name,
+        company_code=company.company_code,
+        company_name=company.company_name,
+    )
+
+
+def _organization(row) -> UserOrganization:
+    org, dept, place, company, parent_name = row
+    return UserOrganization(
+        organization_id=str(org.organization_id),
+        department=_department(dept, place, company, parent_name),
+        primary_company_yn=org.primary_company_yn,
+        primary_department_yn=org.primary_department_yn,
+        employee_no=org.employee_no,
+        rank_cd=org.rank_cd,
+        title_cd=org.title_cd,
+        employment_status_cd=org.employment_status_cd,
+        employment_type_cd=org.employment_type_cd,
+        hire_date=org.hire_date,
+        leave_date=org.leave_date,
+    )
+
+
+def _privacy(periods: list[PrivacyHandlerLog], released: bool, today: date) -> UserPrivacy:
+    if not periods or released:
+        return UserPrivacy(state="unassigned")
+    started = [period for period in periods if period.start_date <= today]
+    current = started[-1] if started else None
+    if current and (current.finish_date is None or current.finish_date >= today):
+        state, period = "active", current
+    else:
+        future = next((period for period in periods if period.start_date > today), None)
+        state, period = ("scheduled", future) if future else ("expired", periods[-1])
+    return UserPrivacy(
+        state=state,
+        start_date=period.start_date,
+        finish_date=period.finish_date,
+        remaining_days=(period.finish_date - today).days if state == "active" and period.finish_date else None,
+        view=period.privacy_view_yn,
+        process=period.privacy_process_yn,
+        export=period.privacy_export_yn,
+    )
+
+
+def _phone(user: UserBasic, field: Literal["mobile_phone", "home_phone"], *, masked: bool) -> str | None:
+    encrypted = user.mobile_phone if field == "mobile_phone" else user.home_phone
+    if encrypted is None:
+        return None
+    try:
+        value = decrypt(get_settings().key_bytes(), encrypted, user_phone_aad(user.user_id, field))
+    except CryptoError:
+        if masked:
+            return "****"
+        raise HTTPException(409, "연락처 원문을 읽을 수 없다") from None
+    return mask_phone(value) if masked else value
+
+
+def _summary(user: UserBasic, primary: UserDepartment | None, privacy: UserPrivacy) -> UserSummary:
+    return UserSummary(
+        user_id=str(user.user_id),
+        login_email=user.login_email,
+        user_name=user.user_name,
+        account_status_cd=user.account_status_cd,
+        directory_suspended_yn=user.directory_suspended_yn is True,
+        primary_department=primary,
+        mobile_phone=_phone(user, "mobile_phone", masked=True),
+        privacy=privacy,
+    )
+
+
+def _not_found() -> HTTPException:
+    return HTTPException(404, "사용자 또는 소속을 찾을 수 없다")
+
+
+class UserAdminService(BaseService):
+    @property
+    def repo(self) -> UserAdminRepository:
+        return UserAdminRepository(self.session)
+
+    async def _places(self, today: date) -> set[int] | None:
+        actor = self.ctx.user
+        if actor is None:
+            raise HTTPException(401, "로그인이 필요하다")
+        if actor.all_menus or await self.repo.is_system_admin(actor.id):
+            return None
+        return await self.repo.member_places(actor.id, today)
+
+    async def _privacy_map(self, user_ids: list[int], today: date) -> dict[int, UserPrivacy]:
+        if not user_ids:
+            return {}
+        grouped = defaultdict(list)
+        for period in await self.repo.privacy_periods(user_ids):
+            grouped[period.user_id].append(period)
+        releases = await self.repo.privacy_releases(user_ids)
+        return {user_id: _privacy(grouped[user_id], user_id in releases, today) for user_id in user_ids}
+
+    async def users(
+        self,
+        search: str | None,
+        business_place_id: int | None,
+        department_id: int | None,
+        status: AccountStatus | None,
+    ) -> UserList:
+        today = get_settings().today()
+        allowed = await self._places(today)
+        selected = allowed
+        if business_place_id is not None:
+            if allowed is not None and business_place_id not in allowed:
+                return UserList(today=today, users=[])
+            selected = {business_place_id}
+        users = await self.repo.users(selected, search.strip() if search else None, department_id, status)
+        if not users:
+            return UserList(today=today, users=[])
+        ids = [user.user_id for user in users]
+        primary: dict[int, UserDepartment] = {}
+        for org, dept, place, company, parent in await self.repo.organizations(ids, allowed, primary_only=True):
+            primary.setdefault(org.user_id, _department(dept, place, company, parent))
+        privacy = await self._privacy_map(ids, today)
+        return UserList(
+            today=today,
+            users=[_summary(row, primary.get(row.user_id), privacy[row.user_id]) for row in users],
+        )
+
+    async def detail(self, user_id: int) -> UserDetail:
+        today = get_settings().today()
+        allowed = await self._places(today)
+        rows = await self.repo.organizations([user_id], allowed)
+        if allowed is not None and not rows:
+            raise _not_found()
+        user = await self.session.get(UserBasic, user_id)
+        if user is None:
+            raise _not_found()
+        organizations = [_organization(row) for row in rows]
+        primary = next((row.department for row in organizations if row.primary_department_yn), None)
+        privacy = (await self._privacy_map([user_id], today))[user_id]
+        return UserDetail(
+            **_summary(user, primary, privacy).model_dump(),
+            profile_name=user.profile_name,
+            gender_cd=user.gender_cd,
+            invite_dt=user.invite_dt,
+            invite_expire_dt=user.invite_expire_dt,
+            last_login_dt=await self.repo.last_login(user_id),
+            home_phone=_phone(user, "home_phone", masked=True),
+            address="****" if user.address else None,
+            first_hire_date=user.first_hire_date,
+            last_leave_date=max((row.leave_date for row in organizations if row.leave_date is not None), default=None),
+            use_language_cd=user.use_language_cd,
+            discord_account="****" if user.discord_account else None,
+            organizations=organizations,
+        )
+
+    async def contacts(self, user_id: int, business_place_id: int) -> UserContact:
+        today = get_settings().today()
+        allowed = await self._places(today)
+        if (allowed is not None and business_place_id not in allowed) or not await self.repo.organizations(
+            [user_id], {business_place_id}
+        ):
+            raise _not_found()
+        user = await self.session.get(UserBasic, user_id)
+        if user is None:
+            raise _not_found()
+        contact = UserContact(
+            mobile_phone=_phone(user, "mobile_phone", masked=False),
+            home_phone=_phone(user, "home_phone", masked=False),
+            address=user.address,
+            discord_account=user.discord_account,
+        )
+        await self.audit(CONTACT_VIEW_EVENT, target=f"business_place:{business_place_id}/user:{user_id}")
+        await self.commit()
+        return contact
