+"""P045 S-1–S-3 through real authentication and isolated MySQL."""
+
+import base64
+from contextlib import AsyncExitStack
+from datetime import date, datetime, timedelta
+
+import httpx
+import pytest
+from sqlalchemy import select
+
+from app.main import create_app
+from core import db
+from core.audit import AuditLog
+from core.auth.models import LoginSession
+from core.auth.sessions import issue_session, key_hash, session_cookie
+from core.config import get_settings
+from core.crypto import encrypt
+from core.history import ChangeLog, ChangeType
+from core.identity import AccountStatus, UserBasic, UserLanguage, user_phone_aad
+from domains.worklink.models.organization.business_place_basic import BusinessPlaceBasic
+from domains.worklink.models.organization.company_basic import CompanyBasic
+from domains.worklink.models.organization.department_basic import DepartmentBasic
+from domains.worklink.models.organization.organization import Organization
+from domains.worklink.models.organization.privacy_handler_log import PrivacyHandlerLog
+from domains.worklink.models.system.menu_basic import MenuBasic
+from domains.worklink.models.system.role import Role
+from domains.worklink.models.system.user_menu import UserMenu, UserMenuSource
+from domains.worklink.repository.system.user_admin import CONTACT_VIEW_EVENT, PRIVACY_TARGET
+
+pytestmark = [pytest.mark.db, pytest.mark.anyio]
+URL = "/api/worklink/system/user"
+START = date(2026, 9, 1)
+FINISH = START + timedelta(days=31)
+
+
+@pytest.fixture
+async def portal(migrated, fresh_engine, monkeypatch):
+    monkeypatch.setenv("FINLINK_DATA_KEY", base64.urlsafe_b64encode(b"u" * 32).decode())
+    get_settings.cache_clear()
+    settings = get_settings()
+    app = create_app()
+    today = [START]
+    monkeypatch.setattr(type(settings), "today", lambda _: today[0])
+    user_ids, keys, place_ids, dept_ids = {}, {}, [], []
+    async with db.sessions().begin() as session:
+        company = CompanyBasic(
+            company_code="87", company_name="합성 P045 회사", legal_business_name="합성 법인", amaranth_use_yn=False
+        )
+        session.add(company)
+        await session.flush()
+        for number in (1, 2):
+            code = f"87{number:02}"
+            place = BusinessPlaceBasic(
+                company_id=company.company_id,
+                business_place_code=code,
+                business_place_country_code="JP",
+                business_place_name=f"합성 사업장 {number}",
+                legal_business_name="합성 법인",
+                tax_invoice_issue_yn=False,
+                withholding_tax_return_method_cd="none",
+            )
+            session.add(place)
+            await session.flush()
+            department = DepartmentBasic(
+                business_place_id=place.business_place_id,
+                department_code=f"{code}-001",
+                department_type_cd="department",
+                department_name=f"합성 부서 {number}",
+                use_yn=True,
+                start_date=date(2020, 1, 1),
+                sort_order=1,
+                finance_department_yn=False,
+            )
+            session.add(department)
+            await session.flush()
+            place_ids.append(place.business_place_id)
+            dept_ids.append(department.department_id)
+        admin_role = await session.scalar(select(Role.role_id).where(Role.fixed_role_yn.is_(True)))
+        menu = await session.scalar(select(MenuBasic.menu_id).where(MenuBasic.menu_code == "screen-us-01"))
+        for name in ("viewer", "hidden", "admin", "target", "outside", "invited", "never"):
+            user = UserBasic(
+                user_name=f"합성 P045 {name}",
+                login_email=f"p045-{name}@example.invalid",
+                account_status_cd=AccountStatus.INVITED if name == "invited" else AccountStatus.ACTIVE,
+                use_language_cd=UserLanguage.KOREAN,
+                system_role_id=admin_role if name == "admin" else 1,
+                address="합성 주소 45" if name == "target" else None,
+            )
+            session.add(user)
+            await session.flush()
+            if name == "target":
+                user.mobile_phone = encrypt(
+                    settings.key_bytes(), "010-0000-0145", user_phone_aad(user.user_id, "mobile_phone")
+                )
+                user.home_phone = encrypt(
+                    settings.key_bytes(), "02-0000-0145", user_phone_aad(user.user_id, "home_phone")
+                )
+            user_ids[name] = user.user_id
+            if name in {"viewer", "hidden", "admin"}:
+                keys[name] = issue_session(session, user.user_id, None, settings)
+            if name in {"viewer", "admin"}:
+                session.add(
+                    UserMenu(
+                        user_id=user.user_id,
+                        menu_id=menu,
+                        menu_access_level_cd="1",
+                        user_menu_source_cd=UserMenuSource.DIRECT,
+                        sort_order=1,
+                    )
+                )
+        for name, department, primary, left in (
+            ("viewer", dept_ids[0], True, None),
+            ("hidden", dept_ids[0], True, None),
+            ("target", dept_ids[0], False, date(2026, 8, 2)),
+            ("target", dept_ids[1], True, date(2026, 8, 3)),
+            ("outside", dept_ids[1], True, None),
+            ("invited", dept_ids[0], True, None),
+            ("never", dept_ids[0], True, None),
+        ):
+            session.add(
+                Organization(
+                    user_id=user_ids[name],
+                    department_id=department,
+                    primary_company_yn=primary,
+                    primary_department_yn=primary,
+                    leave_date=left,
+                )
+            )
+        for name in ("viewer", "target"):
+            session.add(
+                PrivacyHandlerLog(
+                    user_id=user_ids[name],
+                    start_date=START,
+                    finish_date=FINISH,
+                    privacy_view_yn=True,
+                    privacy_process_yn=True,
+                    privacy_export_yn=False,
+                )
+            )
+        for name, day, result in (
+            ("target", 10, "success"),
+            ("target", 13, "success"),
+            ("target", 15, "denied"),
+            ("outside", 16, "success"),
+        ):
+            session.add(
+                AuditLog(
+                    create_user_id=user_ids[name],
+                    create_dt=datetime(2026, 7, day, 9),
+                    event_code=f"auth.login.{result}",
+                )
+            )
+    async with AsyncExitStack() as stack, db.sessions()() as session:
+        clients = {}
+        for name, key in keys.items():
+            login = await session.scalar(
+                select(LoginSession).where(LoginSession.session_key_hash_content == key_hash(key))
+            )
+            clients[name] = await stack.enter_async_context(
+                httpx.AsyncClient(
+                    transport=httpx.ASGITransport(app=app),
+                    base_url="http://p045.test",
+                    cookies={session_cookie(settings): key},
+                    headers={"X-CSRF-Token": login.csrf_token_content},
+                )
+            )
+        clients["anonymous"] = await stack.enter_async_context(
+            httpx.AsyncClient(transport=httpx.ASGITransport(app=app), base_url="http://p045.test")
+        )
+        try:
+            yield clients, user_ids, place_ids, dept_ids, today
+        finally:
+            get_settings.cache_clear()
+
+
+async def test_list_detail_and_audited_contact_access(portal):
+    clients, users, places, departments, today = portal
+    viewer, admin = clients["viewer"], clients["admin"]
+    target_path = f"{URL}/{users['target']}"
+    contact_path = f"{target_path}/contacts"
+
+    async def list_users(client, **params):
+        response = await client.get(URL, params={"search": "P045", **params})
+        assert response.status_code == 200, response.text
+        assert response.headers["Cache-Control"] == "no-store"
+        return {row["user_id"]: row for row in response.json()["users"]}
+
+    # S-1: list search, filters, masking, and the date boundaries of the displayed status.
+    selected = await list_users(
+        viewer, search="P045-TARGET@", business_place_id=places[0], department_id=departments[0], status="active"
+    )
+    target_id = str(users["target"])
+    assert set(selected) == {target_id}
+    assert selected[target_id]["primary_department"] is None
+    assert selected[target_id]["mobile_phone"] == "010-****-0145"
+    assert set(await list_users(viewer, status="invited")) == {str(users["invited"])}
+    assert await list_users(viewer, business_place_id=places[1]) == {}
+    assert await list_users(viewer, department_id=departments[1]) == {}
+    assert (await list_users(admin))[target_id]["primary_department"]["department_id"] == str(departments[1])
+    for day, state, remaining in (
+        (START - timedelta(days=1), "scheduled", None),
+        (START, "active", 31),
+        (START + timedelta(days=1), "active", 30),
+        (FINISH, "active", 0),
+        (FINISH + timedelta(days=1), "expired", None),
+    ):
+        today[0] = day
+        rows = await list_users(viewer)
+        privacy = rows[target_id]["privacy"]
+        assert (privacy["state"], privacy["remaining_days"]) == (state, remaining)
+        assert rows[str(users["never"])]["privacy"]["state"] == "unassigned"
+    today[0] = START
+
+    # S-2: detail fields, source of latest successful login, and per-scope leave dates.
+    response = await viewer.get(target_path)
+    assert response.status_code == 200, response.text
+    detail = response.json()
+    assert [row["department"]["department_id"] for row in detail["organizations"]] == [str(departments[0])]
+    assert detail["last_login_dt"] == "2026-07-13T09:00:00"
+    assert detail["last_leave_date"] == "2026-08-02"
+    assert detail["address"] == "****"
+    assert detail["home_phone"] == "020-****-0145"
+    assert (await admin.get(target_path)).json()["last_leave_date"] == "2026-08-03"
+
+    async def contact(client, path=contact_path, place=places[0]):
+        return await client.post(path, json={"business_place_id": str(place)})
+
+    # S-3: per-session authorization and uniform misses for inaccessible or unknown targets.
+    assert (await clients["anonymous"].get(URL)).status_code == 401
+    assert (await clients["hidden"].get(URL)).status_code == 403
+    assert (await clients["hidden"].get(target_path)).status_code == 403
+    assert (await contact(clients["anonymous"])).status_code == 401
+    assert (await contact(clients["hidden"])).status_code == 403
+    outside = f"{URL}/{users['outside']}"
+    assert (await viewer.get(outside)).status_code == 404
+    assert (await admin.get(outside)).status_code == 200
+    misses = [
+        await contact(viewer, place=places[1]),
+        await contact(viewer, path=f"{outside}/contacts"),
+        await contact(viewer, place=99999999),
+    ]
+    assert all(response.status_code == 404 and response.json() == misses[0].json() for response in misses)
+    assert (await contact(admin)).status_code == 403
+    for day in (START - timedelta(days=1), FINISH + timedelta(days=1)):
+        today[0] = day
+        assert (await contact(viewer)).status_code == 403
+    today[0] = START
+    allowed = await contact(viewer)
+    assert allowed.status_code == 200, allowed.text
+    assert allowed.headers["Cache-Control"] == "no-store"
+    assert allowed.json()["mobile_phone"] == "010-0000-0145"
+    assert allowed.json()["address"] == "합성 주소 45"
+    assert allowed.json()["home_phone"] == "02-0000-0145"
+    async with db.sessions().begin() as session:
+        period = await session.scalar(select(PrivacyHandlerLog).where(PrivacyHandlerLog.user_id == users["viewer"]))
+        period.privacy_view_yn = False
+    assert (await contact(viewer)).status_code == 403
+
+    async with db.sessions().begin() as session:
+        period = await session.scalar(select(PrivacyHandlerLog).where(PrivacyHandlerLog.user_id == users["viewer"]))
+        period.privacy_view_yn = True
+        for user_id in (users["viewer"], users["target"]):
+            session.add(
+                ChangeLog(
+                    change_type_cd=ChangeType.UPDATE,
+                    work_target_type_code=PRIVACY_TARGET,
+                    work_target_id=str(user_id),
+                    change_after_content={"designated": False},
+                    create_user_id=users["admin"],
+                )
+            )
+    assert (await list_users(viewer))[target_id]["privacy"]["state"] == "unassigned"
+    assert (await contact(viewer)).status_code == 403
+
+    async with db.sessions()() as session:
+        audits = (await session.scalars(select(AuditLog).where(AuditLog.event_code == CONTACT_VIEW_EVENT))).all()
+        assert len(audits) == 1
+        assert audits[0].create_user_id == users["viewer"]
+        assert audits[0].target_content == f"business_place:{places[0]}/user:{target_id}"
+        assert audits[0].create_dt is not None
+        assert audits[0].remark_content is None
